_choice_task() {
    _argc_util_cache 60 _helper_gradle_tasks_uncached "gradle-tasks:${argc_project_dir:-$PWD}"
}

_helper_gradle_tasks_uncached() {
    local project="${argc_project_dir:-}"
    if [[ -n "$project" ]]; then
        project="$(cd "$project" 2>/dev/null && pwd)" || project=""
    else
        project="$(_argc_util_path_search_parent -p settings.gradle settings.gradle.kts settings.gradle.dcl build.gradle build.gradle.kts build.gradle.dcl)"
    fi
    [[ -n "$project" ]] || return 0
    (cd "$project" && command gradle -q --console=plain tasks --all 2>/dev/null) | gawk '
        function emit(line,   name, desc) {
            if (line ~ /^Pattern: /) return
            if (index(line, " - ") == 0) {
                if (line !~ /[[:space:]]/) print line
                return
            }
            name = line
            sub(/ - .*/, "", name)
            if (name ~ /[[:space:]]/) return
            desc = line
            sub(/^[^ ]+ - /, "", desc)
            print name "\t" desc
        }
        {
            line = $0
            if (line ~ /^[[:space:]]*$/) next
            if (line ~ /^-+$/) { pending = ""; next }
            if (pending != "") emit(pending)
            pending = line
        }
        END { if (pending != "") emit(pending) }
    '
}
